// Atoms (pieces of state)
const countAtom = atom(0);
const userAtom = atom({ name: '', email: '' });

// Derived atoms
const doubleCountAtom = atom(
  (get) => get(countAtom) * 2
);

// Write-only atoms
const incrementAtom = atom(
  null,
  (get, set) => set(countAtom, get(countAtom) + 1)
);

