// Atoms
const countState = atom({
  key: 'countState',
  default: 0
});

const userState = atom({
  key: 'userState',
  default: { name: '', email: '' }
});

// Selectors (derived state)
const doubleCountState = selector({
  key: 'doubleCountState',
  get: ({ get }) => {
    const count = get(countState);
    return count * 2;
  }
});

// Component
