import useSWR, { mutate } from 'swr';
import { SWRConfig } from 'swr';

// Fetcher function
const fetcher = (url) => fetch(url).then(res => res.json());

// Global configuration
function App() {
  return (
    <SWRConfig 
      value={{
        fetcher,
        refreshInterval: 3000,
        revalidateOnFocus: true
      }}
    >
      <UserList />
    </SWRConfig>
  );
}

// Basic usage
